DELIMITER $$
--
-- Functions
--
CREATE DEFINER=`root`@`localhost` FUNCTION `mask_student_id` (`student_id` VARCHAR(20)) RETURNS VARCHAR(20) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci DETERMINISTIC BEGIN
    IF student_id IS NULL THEN RETURN 'UNKNOWN'; END IF;
    RETURN CONCAT(
        SUBSTRING_INDEX(student_id, '-', 1),  -- Keep 'STU'
        '-XXXX-',
        SUBSTRING_INDEX(student_id, '-', -1)   -- Keep last part
    );
END$$

DELIMITER ;

